    def test_update_single_field(self, unit_test_db: Session):
        """测试update - 单字段更新
        
        符合标准: testing-standards.md 第2.3节 - 只更新一个字段，验证其他字段不变
        模式: ORM自动跟踪 - 修改entity属性后调用update方法
        """
        # 准备测试数据
        from tests.factories.user_auth_factories import UserFactory
        from tests.factories.user_auth_factories import UserAuthFactoryManager
        from tests.factories.shopping_cart_factories import CartFactory
        from tests.factories.product_catalog_factories import ProductFactory
        from tests.factories.product_catalog_factories import ProductCatalogFactoryManager
        # 创建最小实体（用于更新测试）
        # 设置user_auth模块所有Factory的session
        UserAuthFactoryManager.setup_factories(unit_test_db)
        # 准备依赖实体: User (跨模块)
        user = UserFactory.create()
        # 准备依赖实体: Cart (同模块)
        CartFactory._meta.sqlalchemy_session = unit_test_db
        cart = CartFactory.create(user_id=user.id)
        # 设置product_catalog模块所有Factory的session
        ProductCatalogFactoryManager.setup_factories(unit_test_db)
        # 准备依赖实体: Product (跨模块)
        product = ProductFactory.create()
        
        # 构造被测实体: CartItem - 只填必填字段
        entity = CartItem(
            quantity=10,
            unit_price=Decimal("99.99"),
            cart_id=cart.id,
            sku_id=product.id
        )
        unit_test_db.add(entity)
        unit_test_db.commit()
        original_quantity = entity.quantity
        
        # 修改实体属性
        entity.name = "更新后数据"
        
        # 执行Repository方法（ORM会自动跟踪变更）
        CartItemRepository(unit_test_db).update(entity)
        unit_test_db.commit()
        
        # 验证目标字段已更新
        assert entity.name == "更新后数据"
        
        # ✅ 验证其他字段未变化
        assert entity.quantity == original_quantity
        
        # 验证数据库已更新
        unit_test_db.expire_all()
        db_entity = unit_test_db.query(CartItem).filter_by(id=entity.id).first()
        assert db_entity.name == "更新后数据"
        assert db_entity.quantity == original_quantity
    
